<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/bootstrap.php';Auth::requireOwner();$actor=(string)($_GET['actor']??'');$where=$actor&&in_array($actor,['owner','agent','customer','system','anonymous'],true)?' WHERE a.actor_type='.db()->quote($actor):'';$rows=db()->query("SELECT a.*,p.name project_name,t.title task_title FROM audit_logs a LEFT JOIN projects p ON p.id=a.project_id LEFT JOIN tasks t ON t.id=a.task_id".$where." ORDER BY a.id DESC LIMIT 600")->fetchAll();AdminUi::header('سجل العمليات','audit');echo AdminUi::flash();?><div class="toolbar"><a class="btn secondary" href="audit.php">الكل</a><?php foreach(['owner'=>'المالك','agent'=>'وكيل','customer'=>'عميل','system'=>'النظام','anonymous'=>'زائر غير مسجل'] as $k=>$l):?><a class="btn secondary" href="?actor=<?=$k?>"><?=$l?></a><?php endforeach?></div><section class="card"><div class="card-title"><div><h2>سجل العمليات</h2><span class="muted small">مين عمل إيه، فين وإمتى، وعلى أي مشروع أو مهمة، والنتيجة</span></div></div><div class="table-wrap"><table><thead><tr><th>#</th><th>الفاعل</th><th>العملية</th><th>الكيان</th><th>المشروع</th><th>المهمة</th><th>النتيجة</th><th>عنوان الاتصال</th><th>الوقت</th></tr></thead><tbody><?php foreach($rows as $a):?><tr><td>#<?=$a['id']?></td><td><?=e(AdminUi::label($a['actor_type']).' '.($a['actor_id']?:''))?></td><td class="mono"><?=e(AdminUi::label($a['action']))?></td><td><?=e(AdminUi::label($a['entity_type']?:'').' '.($a['entity_id']?'#'.$a['entity_id']:''))?></td><td><?=e($a['project_name']?:'—')?></td><td><?=e($a['task_title']?:'—')?></td><td><?=AdminUi::badge($a['result'])?></td><td class="mono"><?=e($a['ip_address']?:'—')?></td><td><?=e(AdminUi::date($a['created_at']))?></td></tr><?php endforeach?></tbody></table></div></section><?php AdminUi::footer();
